    private static <T extends Block> DeferredBlock<T> reg(String name, Supplier<T> block) {
        DeferredBlock<T> b = ModBlocks.BLOCKS.register(name, block);
        if (name.endsWith("_door")) ModItems.ITEMS.register(name, () -> new DoubleHighBlockItem(b.get(), new Item.Properties()));
        else ModItems.ITEMS.register(name, () -> new BlockItem(b.get(), new Item.Properties()));
        ALL.add(b);
        return b;
    }
    @SuppressWarnings("unchecked")
    private static DeferredItem<Item> item(String name, Supplier<? extends Item> sup) {
        DeferredItem<Item> it = (DeferredItem<Item>) (DeferredItem<?>) ModItems.ITEMS.register(name, sup);
        ITEMS.add(it);
        return it;
    }
    public static void init() { QuantumFalcon.LOGGER.info("Quantum Falcon: {} derived blocks queued", ALL.size()); }
    private ModDerivedBlocks() {}
